nguage'=>'Nuna harshen da ake ciki yanzu','block titleLanguage switcher (sample)'=>'Mai sauya harshe (misali)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Ana lissafa harsunan shafin daga matosai na fassara, idan akwai mai aiki. Ba ya nuna komai in ba haka ba.','block keywordlanguage'=>'Harshe','block keywordswitcher'=>'mai sauyawa','block titleSample content'=>'Samfurin abun ciki','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Wani take da sakin layi, waɗanda aka nuna da sunayen aji marasa ɓata guda. Shi ne tubalin misali don kwangilar fassara.','block keywordsample'=>'misali','block keywordtext'=>'rubutu']];